def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
    opp_d = n - opp_c
    opp_rate = (opp_c + 1.0) / (n + 2.0)

    last_mine, last_opp = history[-1]
    prev_mine = history[-2][0] if n >= 2 else 'C'

    recent_start = 0 if n <= 8 else n - 8
    recent_opp_c = 0
    recent_opp_d = 0
    for i in range(recent_start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
        else:
            recent_opp_d += 1

    soft = 0
    punish = 0
    recent_soft = 0
    recent_punish = 0
    recent_unprov = 0
    resp_start = 1 if n <= 10 else n - 10

    for i in range(1, n):
        pm = history[i - 1][0]
        op = history[i][1]

        if pm == 'D' and history[i - 1][1] == 'C':
            if op == 'C':
                soft += 1
                if i >= resp_start:
                    recent_soft += 1
            else:
                punish += 1
                if i >= resp_start:
                    recent_punish += 1
        elif pm == 'C' and op == 'D':
            if i >= resp_start:
                recent_unprov += 1

    if opp_d == n:
        return 'D'
    if opp_rate <= 0.32:
        return 'D'
    if n >= 6 and opp_d >= opp_c + 2:
        return 'D'

    if last_opp == 'D':
        if recent_opp_d >= recent_opp_c + 2 or recent_unprov >= 2 or recent_opp_d >= 5:
            return 'D'

        if last_mine == 'D':
            if recent_unprov >= 3 and opp_rate < 0.55:
                return 'D'
            return 'C'

        if n >= 2 and prev_mine == 'D':
            return 'C'

        if opp_rate >= 0.62 and recent_unprov <= 1 and recent_opp_d <= 2:
            return 'C'

        return 'D'

    if last_mine == 'D':
        if n < 2:
            return 'C'
        if history[-2][0] == 'C' and recent_soft == 0:
            return 'C'

    if opp_d == 0 and last_mine == 'C' and n >= 4:
        return 'D'

    if recent_punish == 0 and soft > 0:
        if punish == 0:
            if opp_rate >= 0.62 and recent_opp_d == 0:
                return 'D'
        else:
            lenient = (soft + 1.0) / (soft + punish + 2.0)
            if lenient >= 0.75 and opp_rate >= 0.70 and recent_opp_d <= 1 and soft >= 3:
                return 'D'
            if n >= 90 and lenient >= 0.68 and opp_rate >= 0.65 and recent_opp_d <= 2 and soft >= 2:
                return 'D'

    return 'C'
